   120	    }
   121	
   122	    /**
   123	     * Determine whether the simulation is still viable.
   124	     * I.e., should it continue to run.
   125	     * @return true If there is more than one species alive.
   126	     */
   127	    public boolean isViable(Field field)
   128	    {
   129	        // How many counts are non-zero.
   130	        Set<Class> aliveSpecies = new HashSet<>();
   131	        int nonZero = 0;
   132	        if(!countsValid) {
   133	            generateCounts(field);
   134	        }
   135	        for(Class key : counters.keySet()) {
   136	            Counter info = counters.get(key);
   137	            if(info.getCount() > 0) {
   138	                nonZero++;
   139	                aliveSpecies.add(key);
   140	            }
   141	        }
   142	
   143	        // if viability is to be defined based on the species in the field as well, use the aliveSpecies Set
   144	        // eg: return nonZero > 2 && aliveSpecies.contains(Deer.class)
   145	
   146	        return nonZero > 2;
   147	    }
   148	    
   149	    /**
   150	     * Generate counts of the number of organisms.
   151	     * These are not kept up to date as organisms.
   152	     * are placed in the field, but only when a request
   153	     * is made for the information.
   154	     * @param field The field to generate the stats for.
   155	     */
   156	    private void generateCounts(Field field)
   157	    {
   158	        reset();
   159	        for(int row = 0; row < field.getDepth(); row++) {
   160	            for(int col = 0; col < field.getWidth(); col++) {
   161	                Object actor = field.getObjectAt(row, col);
   162	                if(actor != null) {
   163	                    incrementCount(actor.getClass());
   164	                    if(actor instanceof Organism){
   165	                        if(((Organism) actor).isDiseased()){
   166	                            incrementDiseasedCount();
   167	                        }
   168	                    }
   169	                }
   170	            }
   171	        }
   172	        countsValid = true;
   173	    }
   174	}

